1	import { test as base } from "@playwright/test";
2	
3	import { e2eConfig, PARALLEL_TAG_PATTERN } from "../config.ts";
4	import type { Actor } from "../lib/actors.ts";
5	import { storageStatePath } from "../lib/auth.ts";
6	import { ensureScenario, restoreScenario } from "../lib/seed.ts";
7	
8	interface E2eOptions {
9	  /**
10	   * Who the browser is signed in as. `anonymous` carries no session, for specs that sign
11	   * in through the UI themselves.
12	   */
13	  actor: Actor;
14	  /** The database state this spec starts from. See `scenarios/`. */
15	  scenario: string;
16	}
17	
18	interface E2eFixtures {
19	  seed: void;
20	}
21	
22	const config = e2eConfig();
23	
24	export const test = base.extend<E2eOptions & E2eFixtures>({
25	  actor: ["admin", { option: true }],
26	  scenario: ["default", { option: true }],
27	
28	  /**
29	   * Puts the database back before the test runs.
30	   *
31	   * `storageState` depends on this rather than it being an `auto` fixture, because the
32	   * ordering is the point: the reset has to finish before the browser context exists, or
33	   * the first page load races a truncated database.
34	   *
35	   * A test tagged `parallel()` skips the reset entirely - that is what lets those run in
36	   * parallel with each other. The database their group shares was restored once, by the
37	   * group's `restore:<scenario>` project.
38	   */
39	  seed: async ({ scenario }, provide, testInfo) => {
40	    /*
41	     * A tagged test runs on the database its group's restore project put in place, and
42	     * resetting here would pull it out from under the tests running alongside.
43	     */
44	    if (testInfo.tags.some(tag => PARALLEL_TAG_PATTERN.test(tag))) {
45	      await provide();
46	
47	      return;
48	    }
49	
50	    const dumpPath = await ensureScenario(config, scenario);
51	
52	    restoreScenario(config, dumpPath);
53	
54	    await provide();
55	  },
56	
57	  storageState: async ({ actor, seed }, provide) => {
58	    void seed;
59	
60	    if (actor === "anonymous") {
61	      await provide(undefined);
62	
63	      return;
64	    }
65	
66	    await provide(storageStatePath(config, actor));
67	  },
68	});
69	
70	export { expect } from "@playwright/test";
71

