() => {
  const ids = [...document.querySelectorAll('[data-test-id]')].map(e => e.getAttribute('data-test-id')).filter(id => /list|grid|row|search|tab/i.test(id));
  const table = document.querySelector('table');
  const rows = table ? [...table.querySelectorAll('tr')].map(r => r.innerText.replace(/\s+/g,' ')) : null;
  const anchors = [...document.querySelectorAll('a')].filter(a => a.href.includes('/customers/') && /customers\/[A-Za-z0-9%=]+$/.test(a.getAttribute('href')||'')).map(a => ({href: a.getAttribute('href'), cls: a.className, display: a.style.display}));
  const canvas = document.querySelectorAll('canvas').length;
  return { ids: [...new Set(ids)], rows, anchors, canvas, url: location.href };
}

() => {
  const t = document.querySelector('table');
  const tr = [...t.querySelectorAll('tr')][1];
  return {
    tableRole: t.getAttribute('role'), tableAria: t.getAttribute('aria-label'), tableParentTestId: t.closest('[data-test-id]')?.getAttribute('data-test-id'),
    rowRole: tr.getAttribute('role'), rowAttrs: [...tr.attributes].map(a => a.name+'='+a.value),
    cells: [...tr.children].map(c => ({ tag: c.tagName, role: c.getAttribute('role'), attrs: [...c.attributes].map(a=>a.name+'='+a.value).join(' '), text: c.innerText })),
    listEl: document.querySelector('[data-test-id="list"]')?.tagName,
    anchor: (() => { const a = document.querySelector('[data-test-id="datagrid-row-anchor"]'); return a ? { tag: a.tagName, href: a.getAttribute('href'), display: a.style.display } : null })()
  };
}

