async (page) => {
  const cell = page.getByTestId('list').getByRole('gridcell', { name: 'e2e.customer@example.com', exact: true });
  const count = await cell.count();
  const visible = await cell.isVisible();
  const box = await cell.boundingBox();
  let clickResult = 'not tried';
  try { await cell.click({ timeout: 3000 }); clickResult = 'clicked'; } catch (e) { clickResult = 'error: ' + e.message.split('\n')[0]; }
  await page.waitForTimeout(1000);
  return { count, visible, box, clickResult, url: page.url() };
}

