import { expect, test } from "../../fixtures/test.ts";
import { CUSTOMER, ORDERS_SCENARIO } from "../../scenarios/orders.ts";

/**
 * Ticket 06: a staff member holding only the customer-management permission (MANAGE_USERS)
 * finds a customer through the Customers list search, opens her details, writes a note in
 * the Contact card and saves it. The note shows after saving and is still there after a
 * reload. The customer is reached through the search rather than a URL because her id
 * changes with every build of the dump.
 */
test.use({ scenario: ORDERS_SCENARIO, actor: "customer" });

test.describe("Customer note", () => {
  test("Customer manager saves a note on a customer #e2e", async ({ page }) => {
    // Arrange
    // A fixed note is enough: the database is restored before the test.
    const note = "Prefers delivery after 5pm";
    const searchInput = page.getByTestId("search-input");
    const list = page.getByTestId("list");
    const noteField = page.getByTestId("customer-note");
    const emailField = page.getByTestId("customer-email");
    const saveButton = page.getByTestId("button-bar-confirm");
    const unsavedChanges = page.getByTestId("customer-save-composition");

    // Act & Assert
    await test.step("the customer manager finds the customer by email", async () => {
      await page.goto("/customers/");
      await searchInput.fill(CUSTOMER.email);
      // The grid is a canvas; its accessibility table is attached but hidden, so it is only
      // used to wait for the search to land: the header row plus exactly one body row.
      await expect(
        list.getByRole("gridcell", { name: CUSTOMER.email, exact: true, includeHidden: true }),
      ).toBeAttached();
      await expect(
        list.getByRole("gridcell", {
          name: `${CUSTOMER.firstName} ${CUSTOMER.lastName}`,
          exact: true,
          includeHidden: true,
        }),
      ).toBeAttached();
      await expect(list.getByRole("row", { includeHidden: true })).toHaveCount(2);
    });

    await test.step("opening the customer shows her details", async () => {
      // Canvas rows are not clickable DOM: hovering the first body row (below the ~41px
      // header) activates a real row anchor pointing at the customer's details.
      await list.hover({ position: { x: 150, y: 60 } });
      await page.getByTestId("datagrid-row-anchor").click();
      await page.waitForURL(/\/customers\/(?!add)[^/?]+\??$/);

      await expect(emailField).toHaveValue(CUSTOMER.email);
      await expect(page.getByTestId("customer-first-name")).toHaveValue(CUSTOMER.firstName);
      await expect(page.getByTestId("customer-last-name")).toHaveValue(CUSTOMER.lastName);
      // The scenario sets no note, so the later assertion proves the save, not seed data.
      await expect(noteField).toHaveValue("");
      await expect(noteField).toBeEditable();
      await expect(saveButton).toBeDisabled();
    });

    await test.step("writing a note and saving shows the new note", async () => {
      await noteField.fill(note);
      await expect(unsavedChanges).toHaveText("Unsaved changes: details");
      await expect(saveButton).toBeEnabled();

      await saveButton.click();

      await expect(page.getByText("Customer updated", { exact: true })).toBeVisible();
      await expect(unsavedChanges).toBeHidden();
      await expect(noteField).toHaveValue(note);
    });

    await test.step("the note survives a reload", async () => {
      await page.reload();
      // The email being populated means the form has loaded, not the loading skeleton.
      await expect(emailField).toHaveValue(CUSTOMER.email);
      await expect(noteField).toHaveValue(note);
      await expect(saveButton).toBeDisabled();
    });
  });
});

