13	export const hideRowAnchorElement = (anchor: HTMLAnchorElement): void => {
14	  anchor.style.display = "none";
15	  anchor.removeAttribute("href");
16	  delete anchor.dataset.reactRouterPath;
17	};
18	
19	/**
20	 * Canvas cmd/ctrl-click cannot open a tab via dispatchEvent: that click is
21	 * untrusted, so the browser ignores the link default. window.open still runs
22	 * in the user-gesture stack from Glide's onCellClicked.
23	 */
24	export const activateRowAnchor = (
25	  anchor: HTMLAnchorElement | null,
26	  { openInNewTab }: { openInNewTab: boolean },
27	): void => {
28	  if (!anchor?.href) {
29	    return;
30	  }
31	
32	  if (openInNewTab) {
33	    window.open(anchor.href, "_blank", "noopener,noreferrer");
34	
35	    return;
36	  }
37	
38	  anchor.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
39	};
40	
41	export const useRowAnchor = ({
42	  getRowAnchorUrl,
43	  rowMarkers,
44	  availableColumns,
45	  onWheel,
46	}: {
47	  getRowAnchorUrl?: (item: Item) => string;
48	  rowMarkers?: DataEditorProps["rowMarkers"];
49	  availableColumns?: readonly AvailableColumn[];
50	  onWheel?: (event: WheelEvent) => void;
51	}) => {
52	  const rowAnchorRef = useRef<HTMLAnchorElement | null>(null);
53	
54	  useEffect(function hideRowAnchorOnViewportChange() {
55	    const hide = (): void => {
56	      if (rowAnchorRef.current) {
57	        hideRowAnchorElement(rowAnchorRef.current);
58	      }
59	    };
60	
61	    // Wheel on the overlay is handled separately. Keyboard scroll, scrollbar
62	    // drag, and scroller pans never hit that listener — without this, a
63	    // position:fixed href stays under the cursor pointing at the wrong row.
64	    window.addEventListener("scroll", hide, true);
65	    window.addEventListener("resize", hide);
66	
67	    return (): void => {
68	      window.removeEventListener("scroll", hide, true);
69	      window.removeEventListener("resize", hide);
70	    };
71	  }, []);
72	
73	  const setRowAnchorRef = useCallback(
74	    (element: HTMLAnchorElement | null) => {
75	      const previous = rowAnchorRef.current;
76	
77	      if (previous && onWheel) {
78	        previous.removeEventListener("wheel", onWheel);
79	      }
80	
81	      rowAnchorRef.current = element;
82	
83	      // Native listener: React's onWheel is passive, so preventDefault would be ignored.
84	      // Bind on mount so this still attaches after the loading gate unmounts the <a>.
85	      if (element && onWheel) {
86	        element.addEventListener("wheel", onWheel, { passive: false });
87	      }
88	    },
89	    [onWheel],
90	  );
91	
92	  const setAnchorPosition = useCallback(
93	    (args: GridMouseEventArgs) => {
94	      const anchor = rowAnchorRef.current;
95	
96	      if (!anchor) {
97	        return;
98	      }
99	
100	      // Hide immediately (not debounced). Glide ignores moves that land on this
101	      // overlay; a parked anchor would swallow re-entry and freeze the hover row.
102	      if (args.kind !== "cell" || !getRowAnchorUrl) {
103	        hideRowAnchorElement(anchor);
104	
105	        return;
106	      }
107	
108	      const action = getCellAction(availableColumns, args.location[0]);
109	      const href = getRowAnchorUrl(args.location);
110	
111	      if (!href || action) {
112	        hideRowAnchorElement(anchor);
113	
114	        return;
115	      }
116	
117	      if (preventRowClickOnSelectionCheckbox(rowMarkers, args.location[0])) {
118	        hideRowAnchorElement(anchor);
119	
120	        return;
121	      }
122	
123	      // Glide reports viewport bounds; the anchor is position:fixed, so use them as-is.
124	      anchor.style.left = `${args.bounds.x}px`;
125	      anchor.style.width = `${args.bounds.width}px`;
126	      anchor.style.top = `${args.bounds.y}px`;
127	      anchor.style.height = `${args.bounds.height}px`;
128	      anchor.href = withAppMountUri(href);
129	      anchor.dataset.reactRouterPath = href;
130	      anchor.style.display = "block";
131	    },
132	    [availableColumns, getRowAnchorUrl, rowMarkers],
133	  );
134	
135	  return {
136	    rowAnchorRef,
137	    setRowAnchorRef,
138	    setAnchorPosition,
139	  };
140	};
