import { expect, type Page } from "@playwright/test";

/**
 * Glide row geometry (`cellHeight` in `src/components/Datagrid/styles.ts`): header and body
 * rows are both 40px, under a 1px top border. The middle of the first body row is therefore
 * at 1 + 40 + 20 from the top of the list.
 */
const FIRST_BODY_ROW_Y = 61;

/** Clear of the row-marker checkbox column, which does not open the row. */
const FIRST_DATA_COLUMN_X = 150;

/** The Customers list: searching it and opening a customer from the canvas grid. */
export class CustomerListPage {
  readonly searchInput = this.page.getByTestId("search-input");

  readonly list = this.page.getByTestId("list");

  /**
   * The grid is a canvas; Glide mirrors it in an accessibility table that is attached but
   * zero-size, so these are for waiting and asserting, never for clicking. Header included.
   */
  readonly rows = this.list.getByRole("row", { includeHidden: true });

  readonly rowAnchor = this.page.getByTestId("datagrid-row-anchor");

  constructor(readonly page: Page) {}

  /** A cell of the grid's accessibility table, by its exact text. */
  cell(text: string) {
    return this.list.getByRole("gridcell", { name: text, exact: true, includeHidden: true });
  }

  async goto() {
    await this.page.goto("/customers/");
    await this.searchInput.waitFor();
  }

  /**
   * Waits for the grid to narrow to the one matching row: until the debounced search lands
   * the grid re-renders, and a row hovered in the unfiltered one points at another customer.
   */
  async search(query: string) {
    await this.searchInput.fill(query);
    await expect(this.cell(query)).toBeAttached();
    await expect(this.rows).toHaveCount(2);
  }

  /**
   * Canvas rows are not clickable DOM. Hovering a body row moves a real `<a>` over it whose
   * href is that row's details page; waiting for the href proves the hover landed on a row
   * before the click, rather than trusting the offset.
   */
  async openFirstRow() {
    await this.list.hover({ position: { x: FIRST_DATA_COLUMN_X, y: FIRST_BODY_ROW_Y } });
    await expect(this.rowAnchor).toHaveAttribute("href", /\/customers\/(?!add)[^/?]+\??$/);
    await this.rowAnchor.click();
    await this.page.waitForURL(/\/customers\/(?!add)[^/?]+\??$/);
  }
}

import { type Page } from "@playwright/test";

/** A customer's details page: the Contact card and the savebar. */
export class CustomerDetailsPage {
  readonly firstNameInput = this.page.getByTestId("customer-first-name");

  readonly lastNameInput = this.page.getByTestId("customer-last-name");

  readonly emailInput = this.page.getByTestId("customer-email");

  readonly noteInput = this.page.getByTestId("customer-note");

  readonly saveButton = this.page.getByTestId("button-bar-confirm");

  readonly unsavedChanges = this.page.getByTestId("customer-save-composition");

  readonly updatedNotification = this.page.getByText("Customer updated", { exact: true });

  constructor(readonly page: Page) {}

  /** The loading skeleton is a separate layout without the form, so the note marks a load. */
  async reload() {
    await this.page.reload();
    await this.noteInput.waitFor();
  }

  async fillNote(note: string) {
    await this.noteInput.fill(note);
  }

  async save() {
    await this.saveButton.click();
    await this.updatedNotification.waitFor();
  }
}

import { expect, test } from "../../fixtures/test.ts";
import { CustomerDetailsPage } from "../../pages/customerDetailsPage.ts";
import { CustomerListPage } from "../../pages/customerListPage.ts";
import { CUSTOMER, ORDERS_SCENARIO } from "../../scenarios/orders.ts";

/**
 * Ticket 06: a staff member holding only the customer-management permission (MANAGE_USERS)
 * finds a customer through the Customers list search, opens her details, writes a note in
 * the Contact card and saves it. The note shows after saving and is still there after a
 * reload. The customer is reached through the search rather than a URL because her id
 * changes with every build of the dump.
 */
test.use({ scenario: ORDERS_SCENARIO, actor: "customer" });

test.describe("Customer note", () => {
  test("Customer manager saves a note on a customer #e2e", async ({ page }) => {
    // Arrange
    // A fixed note is enough: the database is restored before the test.
    const note = "Prefers delivery after 5pm";
    const customerList = new CustomerListPage(page);
    const customerDetails = new CustomerDetailsPage(page);

    // Act & Assert
    await test.step("the customer manager finds the customer by email", async () => {
      await customerList.goto();
      await customerList.search(CUSTOMER.email);

      await expect(customerList.cell(CUSTOMER.email)).toBeAttached();
      await expect(
        customerList.cell(`${CUSTOMER.firstName} ${CUSTOMER.lastName}`),
      ).toBeAttached();
      // The header row plus exactly one body row.
      await expect(customerList.rows).toHaveCount(2);
    });

    await test.step("opening the customer shows her details", async () => {
      await customerList.openFirstRow();

      await expect(customerDetails.emailInput).toHaveValue(CUSTOMER.email);
      await expect(customerDetails.firstNameInput).toHaveValue(CUSTOMER.firstName);
      await expect(customerDetails.lastNameInput).toHaveValue(CUSTOMER.lastName);
      // The scenario sets no note, so the later assertion proves the save, not seed data.
      await expect(customerDetails.noteInput).toHaveValue("");
      await expect(customerDetails.noteInput).toBeEditable();
      await expect(customerDetails.saveButton).toBeDisabled();
    });

    await test.step("writing a note and saving shows the new note", async () => {
      await customerDetails.fillNote(note);

      await expect(customerDetails.unsavedChanges).toHaveText("Unsaved changes: details");
      await expect(customerDetails.saveButton).toBeEnabled();

      await customerDetails.save();

      await expect(customerDetails.updatedNotification).toBeVisible();
      await expect(customerDetails.unsavedChanges).toBeHidden();
      await expect(customerDetails.noteInput).toHaveValue(note);
    });

    await test.step("the note survives a reload", async () => {
      await customerDetails.reload();

      await expect(customerDetails.emailInput).toHaveValue(CUSTOMER.email);
      await expect(customerDetails.noteInput).toHaveValue(note);
      await expect(customerDetails.saveButton).toBeDisabled();
    });
  });
});

